// Separate same-agent reader. It does not import the producer or execute provers.
use std::{collections::{BTreeMap,BTreeSet},fs,io::Read,os::unix::fs::MetadataExt,path::{Path,PathBuf}};
use serde_json::{json,Value};use sha2::{Digest,Sha256};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn near(a:f64,b:f64){assert!(a.is_finite()&&b.is_finite()&&(a-b).abs()<=1e-10*a.abs().max(b.abs()).max(1.));}
fn receipt(p:&Path,argv:&Value){let e=read(p.join("exit.json"));assert_eq!(e["success"],true);assert_eq!(e["returncode"],0);for s in["stdout","stderr"]{assert_eq!(hash(p.join(format!("{s}.log"))),e[format!("{s}_sha256")].as_str().unwrap());}let c=read(p.join("command.json"));let a=c["argv"].as_array().unwrap();assert_eq!(&a[..3],&[json!("timeout"),json!("-k"),json!("5s")]);assert_eq!(&a[4..],argv.as_array().unwrap());}
fn main(){
    let a=std::env::args().collect::<Vec<_>>();let root=Path::new(&a[1]);let smoke=false;assert_eq!(a[2],"capture");let stage=a[3].as_str();assert!(["plan","preflight","finish"].contains(&stage));
    let out=root.join(if smoke{"smoke-output"}else{"output"});let cfg=read(root.join("config/config.json"));let jobs=read(out.join("jobs.json"));let js=jobs.as_array().unwrap();let steps=read(out.join("capture-steps.json"));let st=steps.as_array().unwrap();assert_eq!(js.len(),78);assert_eq!(st.len(),js.len());
    let payload=read(root.join("payload-pins.json"));for(p,h)in payload.as_object().unwrap(){assert_eq!(hash(root.join(p)),h.as_str().unwrap());}
    let runtime=read(out.join("runtime-pins.json"));for(p,h)in runtime.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}
    let mut all_inodes=BTreeSet::new();let bs=read(out.join("backings.json"));assert_eq!(bs.as_array().unwrap().len(),6);
    for b in bs.as_array().unwrap(){let family=b["family"].as_str().unwrap();assert!(["sdk","aeglos"].contains(&family));let n=b["backing"].as_u64().unwrap();assert!(n<3);let p=out.join(format!("{family}{n}"));assert_eq!(b["path"],p.display().to_string());let m=fs::metadata(&p).unwrap();assert_eq!(b["dev"],m.dev());assert_eq!(b["inode"],m.ino());assert!(all_inodes.insert((m.dev(),m.ino())));assert_eq!(hash(&p),cfg[format!("{family}_sha256")].as_str().unwrap());}
    for(f,h)in[("sdk","d523f49e8548620c4373a1ab4be2712d705709fdd7a590c5ed73e9aff97424e3"),("aeglos","eab9fbfd4b94aeef9ced3ce3e3ede21a37ab70ad38b217720f1afd06fceba99b")]{assert_eq!(cfg[format!("{f}_sha256")],h);}
    let contexts=[("1x2",32,"ON"),("1x2",32,"AEGLOS"),("1x2",96,"ON"),("1x2",96,"AEGLOS"),("merge-54x1",32,"ON"),("merge-54x1",96,"ON")];
    let mut expected=BTreeSet::new();for(s,w,a)in contexts{expected.insert(format!("preflight-{s}-w{w}-{a}-plain-b00"));for b in 0..3{expected.insert(format!("latency-{s}-w{w}-{a}-plain-b{b:02}"));for p in["observer","stat","dual"]{expected.insert(format!("profile-{s}-w{w}-{a}-{p}-b{b:02}"));}}}
    let mut seen=BTreeSet::new();let mut calls=0;let mut timed=0;
    for(i,j)in js.iter().enumerate(){
        let phase=j["phase"].as_str().unwrap();let panel=j["panel"].as_str().unwrap();let pre=i<6;assert_eq!(j["preflight"],pre);assert_eq!(phase,if i<6{"preflight"}else if i<24{"latency"}else{"profile"});
        let block=j["block"].as_u64().unwrap();let s=j["case"]["shape"].as_str().unwrap();let w=j["workers"].as_u64().unwrap();let arm=j["arm"].as_str().unwrap();assert!(contexts.contains(&(s,w as usize,arm)));assert!(block<3);if pre{assert_eq!(block,0);assert_eq!(panel,"plain");}else if phase=="latency"{assert_eq!(panel,"plain");}else{assert!(["observer","stat","dual"].contains(&panel));}
        let n=if pre{1}else if s=="1x2"{251}else{17};let name=format!("{phase}-{s}-w{w}-{arm}-{panel}-b{block:02}");assert!(expected.remove(&name));assert!(seen.insert(name.clone()));assert_eq!(j["name"],name);assert_eq!(j["backing"],block%3);assert_eq!(j["rounds"],n);assert_eq!(j["case"],cfg["cases"][s]);
        let c=&cfg["cases"][s];let family=match arm{"PARENT"=>"parent","AEGLOS"=>"aeglos",_=>"sdk"};let z=arm!="AEGLOS";assert_eq!(j["engine"],if z{"zopro"}else{"aeglos"});let binary=out.join(format!("{family}{}",block%3));assert_eq!(j["binary"],binary.display().to_string());
        let base=out.join("proofs").join(&name);let pd=if z{base.clone()}else{base.join(c["id"].as_str().unwrap())};assert_eq!(j["proof_dir"],pd.display().to_string());
        let mut expected=vec![];let data=j["data"].as_str();
        if panel=="stat"||panel=="dual"{expected.push(json!("/usr/bin/perf"));if panel=="stat"{assert_eq!(data.unwrap(),out.join("stat").join(format!("{name}.csv")).display().to_string());expected.extend(["stat","--no-big-num","-x",";","-e","{cycles:u,instructions:u,cache-misses:u,branch-misses:u}","-o",data.unwrap()].map(|v|json!(v)));}else{assert_eq!(data.unwrap(),out.join("perf").join(format!("{name}.data")).display().to_string());expected.extend(["record","--no-buildid-cache","--sample-cpu","--timestamp","-P","--clockid","mono","-e","cycles:u,instructions:u","-c","16000000","-m","512","-o",data.unwrap()].map(|v|json!(v)));}expected.extend([json!("--delay=-1"),json!(format!("--control=fifo:{},{}",out.join("ctl").display(),out.join("ack").display())),json!("--")]);}else{assert!(j["data"].is_null());}
        expected.extend([json!("/usr/bin/taskset"),json!("-c"),json!(format!("0-{}",w-1)),json!(binary)]);if z{expected.extend([json!(root.join(c["image"].as_str().unwrap())),json!(root.join(c["request"].as_str().unwrap())),json!(n.to_string()),json!(pd)]);}else{expected.extend([json!("aeglos"),json!(root.join(c["aeglos_key"].as_str().unwrap())),json!(root.join(c["request"].as_str().unwrap())),json!(n.to_string())]);}
        assert_eq!(st[i]["argv"],json!(expected));assert_eq!(st[i]["name"],name);assert_eq!(st[i]["timeout_seconds"],300);
        let mut env=cfg["environment"].clone();let replacements=[("RAYON_NUM_THREADS",w.to_string()),("ZOPRO_BASIS_KEY_DIR",root.join("images").display().to_string()),("ZOPRO_CPU_LAGRANGE_DIR",root.join("cache").display().to_string()),("ZOPRO_BENCH_CERTIFIED_OUTPUT","1".into()),("ZOPRO_BENCH_FUSED_PREPARATION","1".into()),("ZOPRO_CPU_INDEXED_TILE_BUNDLES","1".into()),("AEGLOS_CPU_THREADS",w.to_string()),("GOMAXPROCS",w.to_string()),("AEGLOS_BENCH_DISABLE_SHIFTED","0".into()),("AEGLOS_BENCH_MSM_PHASES","0".into()),("ZOPRO_BENCH_MSM_PHASES","0".into()),("ZOPRO_BENCH_PROOFS",base.display().to_string()),("LD_LIBRARY_PATH",root.join("lib").display().to_string())];for(k,v)in replacements{env[k]=json!(v);}if panel=="stat"||panel=="dual"{for k in["ZOPRO_BENCH_PERF_CTL","CROSS_PERF_CTL"]{env[k]=json!(out.join("ctl"));}for k in["ZOPRO_BENCH_PERF_ACK","CROSS_PERF_ACK"]{env[k]=json!(out.join("ack"));}}assert_eq!(st[i]["environment"],env);assert!(env.get("ZOPRO_CPU_PREPARE_MAX_BYTES").is_none());
        calls+=n+3;timed+=n;
    }
    assert!(expected.is_empty());assert_eq!(calls,12696);assert_eq!(timed,12462);
    let seed:BTreeSet<String>=serde_json::from_value(read(root.join("config/seed.json"))).unwrap();assert_eq!(seed.len(),64133);assert_eq!(cfg["seed_count"],seed.len());
    let mut ledger=seed;let mut checked=0;let mut row_summaries=vec![];
    if stage!="plan"{
        let count=if stage=="preflight"{6}else{js.len()};let producer=read(out.join(if stage=="preflight"{"preflight-rows.json"}else{"rows.json"}));assert_eq!(producer.as_array().unwrap().len(),count);
        for(i,j)in js[..count].iter().enumerate(){let name=j["name"].as_str().unwrap();let phase=j["phase"].as_str().unwrap();let dir=out.join(format!("{phase}-run/{name}"));receipt(&dir,&st[i]["argv"]);
            let recorded=read(dir.join("command.json"));for(k,v)in recorded["environment"].as_object().unwrap(){assert_eq!(v,&st[i]["environment"][k]);}for(k,v)in st[i]["environment"].as_object().unwrap(){if k.starts_with("ZOPRO_")||k.starts_with("MALLOC_")||k=="RAYON_NUM_THREADS"{assert_eq!(&recorded["environment"][k],v,"missing required receipt env {k}");}}
            let raw=fs::read_to_string(dir.join("stdout.log")).unwrap();let mut sum=0.;let mut ns=0;let mut summary=None;let z=j["engine"]=="zopro";
            for line in raw.lines(){if let Some(l)=line.strip_prefix("SAMPLE "){let v:Value=serde_json::from_str(l).unwrap();assert_eq!(v["round"],ns);let x=v[if z{"ms"}else{"verified_ms"}].as_f64().unwrap();assert!(x.is_finite()&&x>0.);if !z{assert_eq!(v["cache_hit"],true);}sum+=x;ns+=1;}else if let Some(l)=line.strip_prefix("SUMMARY "){assert!(summary.is_none());summary=Some(serde_json::from_str::<Value>(l).unwrap());}}
            let s=summary.unwrap();let n=j["rounds"].as_u64().unwrap();assert_eq!(ns,n);assert_eq!(s["rounds"],n);assert_eq!(s["priming"],3);assert_eq!(s[if z{"workers"}else{"threads"}],j["workers"]);
            if z{assert_eq!(s["placement_before"],s["placement_after"]);assert_eq!(s["placement_before"]["mode"],"fixed");let wr=s["placement_before"]["worker_rows"].as_array().unwrap();assert_eq!(wr.len(),j["workers"].as_u64().unwrap()as usize);for(k,v)in wr.iter().enumerate(){assert_eq!(v["index"],k);assert_eq!(v["allowed"],json!([k]));}assert_eq!(s["generated_timed_key_scans"],0);assert_eq!(s["generated_timed_fixed_scans"],0);if j["case"]["shape"]=="1x2"{assert_eq!(s["generated_fast_parses"],n);}}
            else{assert_eq!(s["key_sha256"],j["case"]["aeglos_key_sha256"]);}
            let pd=Path::new(j["proof_dir"].as_str().unwrap());assert_eq!(fs::metadata(pd.join("0.proof")).unwrap().len(),164);let ph=hash(pd.join("0.proof"));assert!(ledger.insert(ph.clone()));assert_eq!(hash(pd.join("0.public")),j["case"]["public_sha256"].as_str().unwrap());
            let va=json!([root.join("bin/verify"),root.join(j["case"]["image"].as_str().unwrap()),PathBuf::from(j["case"]["image_sha256"].as_str().unwrap()),pd.join("0.proof"),pd.join("0.public"),PathBuf::from(j["case"]["public_sha256"].as_str().unwrap())]);let vd=out.join(format!("{}-verify-run/verify-{name}",if phase=="preflight"{"preflight"}else{"late"}));receipt(&vd,&va);let verified=fs::read_to_string(vd.join("stdout.log")).unwrap();assert!(verified.contains(&format!("VERIFIED proof_sha256={ph} ")));assert!(verified.contains(&format!(" image_sha256={}",j["case"]["image_sha256"].as_str().unwrap())));
            let row=&producer[i];assert_eq!(row["job"],*j);assert_eq!(row["summary"],s);assert_eq!(row["proof_sha256"],ph);near(row["mean_ms"].as_f64().unwrap(),sum/n as f64);near(row["cpu_ms"].as_f64().unwrap(),(s["user_cpu_ms"].as_f64().unwrap()+s["system_cpu_ms"].as_f64().unwrap())/n as f64);near(row["rss_mib"].as_f64().unwrap(),s["whole_process_maxrss_kib"].as_f64().unwrap()/1024.);checked+=1;row_summaries.push(json!({"name":name,"mean_ms":sum/n as f64,"proof_sha256":ph}));
        }
        let stored:BTreeSet<String>=serde_json::from_value(read(out.join(if stage=="preflight"{"preflight-proof-sha256.json"}else{"proof-sha256.json"}))).unwrap();assert_eq!(stored,ledger);
    }
    let result=json!({"passed":true,"stage":stage,"mode":a[2],"planned_exports":js.len(),"planned_calls":calls,"planned_timed":timed,"checked_exports":checked,"canonical_count":ledger.len(),"rows":row_summaries,"scope":"Separate same-agent frozen plan/raw/receipt/image/public/fresh-proof reader; existing Gnark verdicts checked, no duplicate local verification"});let dest=out.join(format!("independent-{stage}.json"));assert!(!dest.exists());fs::write(dest,serde_json::to_vec_pretty(&result).unwrap()).unwrap();println!("Independent {stage} PASS; {checked} exports checked; inventory {}",ledger.len());
}
